flowchart TD
 A["Diarrhea<br/>more than 3 BMs per day or over 200 g per day"] --> B{"Duration?"}
 B -->|"Under 4 weeks"| C["Acute<br/>usually infectious"]
 B -->|"Over 4 weeks"| D["Chronic<br/>usually non-infectious"]
 C --> E{"Bloody?"}
 E -->|Yes| F["Dysentery<br/>inflammatory infection"]
 E -->|No| G["Other infectious<br/>e.g. Giardia"]
 D --> H{"Bloody?"}
 H -->|Yes| I["IBD"]
 H -->|No| J["IBD, celiac disease,<br/>microscopic colitis"]
 J --> K{"Stool osmotic gap?"}
 K -->|"Over 50"| L["Osmotic"]
 K -->|"Under 50"| M["Secretory"]

flowchart TD
 A["GI bleed"] --> B["Resuscitate first<br/>ABCs, 2 large-bore IVs, fluids, transfusion,<br/>correct coagulopathy"]
 B --> C{"Hematemesis or melena?"}
 C -->|"Yes - upper"| D{"Variceal?"}
 D -->|No| E["IV pantoprazole bolus + infusion<br/>endoscopic Tx"]
 D -->|Yes| F["PPI + octreotide + ABX<br/>band ligation, tamponade, TIPS"]
 C -->|"Hematochezia - lower"| G{"Hemodynamically stable?"}
 G -->|Yes| H["Colonoscopy"]
 G -->|No| I["Upper endoscopy<br/>+/- angiography, surgery consult"]
 H --> J["Source not found:<br/>tagged RBC scan or angiography"]

flowchart TD
 A["Patient needs nutritional support"] --> B{"Functioning gut?"}
 B -->|Yes| C["Enteral nutrition"]
 C --> D{"Expected duration?"}
 D -->|"Under 3 weeks"| E["NG or ND tube"]
 D -->|"Over 6 weeks"| F["Gastrostomy or jejunostomy"]
 B -->|No| G["Parenteral nutrition"]
 G --> H{"NPO long enough?<br/>7 days nourished, 5 days malnourished"}
 H -->|Yes| I["PPN: mostly fat + 10% glucose<br/>or TPN: mostly 25% glucose via central line"]
 H -->|No| J["Wait - do not start TPN yet"]

flowchart TD
 A["Suspected bowel obstruction"] --> B["CT: diagnose and grade<br/>NG suction, IV fluids, correct electrolytes"]
 B --> C{"FATAL signs or peritonitis?"}
 C -->|Yes| D["Surgery"]
 C -->|No| E{"Small or large bowel?"}
 E -->|"Large"| D
 E -->|"Small"| F{"Previous surgery - adhesive?"}
 F -->|"No - non-adhesive"| D
 F -->|"Yes - adhesive"| G["Non-operative management<br/>85% resolve"]
 G -->|"Fails Gastrografin protocol<br/>or no resolution in 24-48 h"| D
